database-binds-named-id.ruleset:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /p/{d} {
      allow read: if database == 'probes';
    }
  }
}

database-binds-default-id.ruleset:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /p/{d} {
      allow read: if database == '(default)';
    }
  }
}

request-path-database-segment-is-named-i.ruleset:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /p/{d} {
      allow read: if request.path[1] == 'probes';
    }
  }
}

request-path-equals-interpolated-path.ruleset:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /p/{d} {
      allow read: if request.path == /databases/$(database)/documents/p/$(d);
    }
  }
}

literal-named-database-match.ruleset:
rules_version = '2';
service cloud.firestore {
  match /databases/probes/documents {
    match /p/{d} {
      allow read: if true;
    }
  }
}

literal-default-database-match.ruleset:
rules_version = '2';
service cloud.firestore {
  match /databases/(default)/documents {
    match /p/{d} {
      allow read: if true;
    }
  }
}

mocked-get-of-default-database-path.ruleset:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /p/{d} {
      allow read: if get(/databases/(default)/documents/c/x).data.v == 1;
    }
  }
}

