two-literal-root-blocks.ruleset:
rules_version = '2';
service cloud.firestore {
  match /databases/probes/documents {
    match /p/{d} {
      allow read: if true;
    }
  }
  match /databases/(default)/documents {
    match /p/{d} {
      allow read: if false;
    }
  }
}

two-literal-root-blocks-swapped.ruleset:
